#include <vector>
#include <numeric>

class Solution {
public:
    bool canPartitionGrid(std::vector<std::vector<int>>& grid) {
        long long s = 0;
        for (const auto& row : grid) {
            for (int val : row) s += val;
        }
        if (s % 2 != 0) return false;
        long long half = s / 2;

        long long pre = 0;
        int m = grid.size(), n = grid[0].size();
        for (int i = 0; i < m - 1; ++i) {
            for (int j = 0; j < n; ++j) pre += grid[i][j];
            if (pre == half) return true;
        }

        pre = 0;
        for (int j = 0; j < n - 1; ++j) {
            for (int i = 0; i < m; ++i) pre += grid[i][j];
            if (pre == half) return true;
        }

        return false;
    }
};

class Solution {
    public boolean canPartitionGrid(int[][] grid) {
        long s = 0;
        for (int[] row : grid) {
            for (int val : row) s += val;
        }
        if (s % 2 != 0) return false;
        long half = s / 2;

        long pre = 0;
        int m = grid.length, n = grid[0].length;
        for (int i = 0; i < m - 1; ++i) {
            for (int j = 0; j < n; ++j) pre += grid[i][j];
            if (pre == half) return true;
        }

        pre = 0;
        for (int j = 0; j < n - 1; ++j) {
